<?php declare(strict_types=1); $title = 'Movimientos de inventario'; $labels=['compra'=>'Compra','venta'=>'Venta','ajuste_entrada'=>'Ajuste de entrada','ajuste_salida'=>'Ajuste de salida','anulacion'=>'Anulación']; ?>
<section>
    <div class="mb-6"><p class="text-sm font-semibold uppercase tracking-wide text-emerald-700">Trazabilidad</p><h1 class="mt-1 text-3xl font-bold tracking-tight text-slate-900">Movimientos de inventario</h1><p class="mt-2 text-sm text-slate-600">Historial de entradas y salidas originadas por compras, ventas, ajustes y anulaciones.</p></div>
    <?php foreach ($errors as $message): ?><div role="alert" class="mb-3 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900"><?= e($message) ?></div><?php endforeach; ?>
    <form method="get" action="<?= e($baseUrl) ?>/movimientos" class="mb-5 grid gap-3 rounded-xl border border-slate-200 bg-white p-4 sm:grid-cols-2 lg:grid-cols-5">
        <label class="text-xs font-semibold text-slate-600 lg:col-span-2">Buscar<input name="q" value="<?= e($filters['q']) ?>" maxlength="100" placeholder="Producto, lote, motivo o referencia" class="mt-1 min-h-11 w-full rounded-lg border border-slate-300 px-3 text-sm font-normal"></label>
        <label class="text-xs font-semibold text-slate-600">Tipo<select name="tipo" class="mt-1 min-h-11 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm font-normal"><option value="">Todos</option><?php foreach ($labels as $code=>$label): ?><option value="<?= e($code) ?>" <?= $filters['tipo']===$code?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
        <label class="text-xs font-semibold text-slate-600">Desde<input type="date" name="desde" value="<?= e($filters['desde']) ?>" class="mt-1 min-h-11 w-full rounded-lg border border-slate-300 px-3 text-sm font-normal"></label>
        <label class="text-xs font-semibold text-slate-600">Hasta<input type="date" name="hasta" value="<?= e($filters['hasta']) ?>" class="mt-1 min-h-11 w-full rounded-lg border border-slate-300 px-3 text-sm font-normal"></label>
        <div class="flex items-end gap-2 sm:col-span-2 lg:col-span-5"><button class="min-h-10 rounded-lg bg-emerald-700 px-4 text-sm font-semibold text-white">Filtrar</button><a href="<?= e($baseUrl) ?>/movimientos" class="inline-flex min-h-10 items-center rounded-lg border border-slate-300 px-4 text-sm font-semibold">Limpiar</a><span class="ml-auto self-center text-xs text-slate-500">Se muestran hasta 500 registros.</span></div>
    </form>
    <div class="mb-5 grid gap-3 sm:grid-cols-3"><div class="rounded-xl border border-slate-200 bg-white p-4"><div class="text-xs uppercase text-slate-500">Movimientos</div><div class="mt-1 text-2xl font-bold"><?= e(number_format((int)$summary['movimientos'])) ?></div></div><div class="rounded-xl border border-emerald-200 bg-emerald-50 p-4"><div class="text-xs uppercase text-emerald-800">Unidades de entrada</div><div class="mt-1 text-2xl font-bold text-emerald-900"><?= e(number_format((float)$summary['entradas'],3)) ?></div></div><div class="rounded-xl border border-red-200 bg-red-50 p-4"><div class="text-xs uppercase text-red-800">Unidades de salida</div><div class="mt-1 text-2xl font-bold text-red-900"><?= e(number_format((float)$summary['salidas'],3)) ?></div></div></div>
    <div class="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table class="min-w-full divide-y divide-slate-200 text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-600"><tr><?php foreach (['Fecha', 'Producto y lote', 'Tipo', 'Variación', 'Motivo', 'Usuario', 'Origen'] as $heading): ?><th class="px-4 py-3"><?= e($heading) ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y divide-slate-100">
    <?php if (!$rows): ?><tr><td colspan="7" class="px-4 py-10 text-center text-slate-500">No se encontraron movimientos para estos filtros.</td></tr><?php endif; ?>
    <?php foreach ($rows as $row): ?><tr><td class="whitespace-nowrap px-4 py-3"><?= e(date('d/m/Y H:i',strtotime($row['creado_en']))) ?></td><td class="px-4 py-3"><strong><?= e($row['producto']) ?></strong><div class="text-xs text-slate-500"><?= e($row['codigo']) ?> · Lote <?= e($row['codigo_lote'] ?? '—') ?></div></td><td class="px-4 py-3"><?= e($labels[$row['tipo']] ?? $row['tipo']) ?></td><td class="whitespace-nowrap px-4 py-3 font-semibold <?= (float)$row['cantidad_delta']<0?'text-red-700':'text-emerald-800' ?>"><?= (float)$row['cantidad_delta']>0?'+':'' ?><?= e(number_format((float)$row['cantidad_delta'],3)) ?> <?= e($row['unidad_medida']) ?></td><td class="max-w-xs px-4 py-3"><?= e($row['motivo'] ?: '—') ?></td><td class="px-4 py-3"><?= e($row['usuario']) ?></td><td class="whitespace-nowrap px-4 py-3"><?php if ($row['compra_id']): ?><a class="text-emerald-800 hover:underline" href="<?= e($baseUrl) ?>/compras/detalle?id=<?= e($row['compra_id']) ?>">Compra #<?= e($row['compra_id']) ?><?= $row['compra_documento']?' · '.e($row['compra_documento']):'' ?></a><?php elseif ($row['venta_id']): ?><a class="text-emerald-800 hover:underline" href="<?= e($baseUrl) ?>/ventas/detalle?id=<?= e($row['venta_id']) ?>">Venta #<?= e($row['venta_id']) ?><?= $row['venta_documento']?' · '.e($row['venta_documento']):'' ?></a><?php else: ?>Ajuste de inventario<?php endif; ?></td></tr><?php endforeach; ?>
    </tbody></table></div>
</section>
